package com.guocheng.mediapocket;
import android.content.SharedPreferences;import org.json.*;import java.net.*;import java.io.*;
/** User-visible diagnostics without exposing configured credentials or tokenized URLs. */
final class ClawConnectionProbe {
 static JSONObject get(String url,String ua)throws Exception{HttpURLConnection c=(HttpURLConnection)new URL(url).openConnection();c.setConnectTimeout(8000);c.setReadTimeout(12000);c.setRequestProperty("User-Agent",ua);c.setRequestProperty("Accept","application/json");try{int code=c.getResponseCode();if(code!=200)throw new IOException("HTTP "+code);try(InputStream in=c.getInputStream();ByteArrayOutputStream out=new ByteArrayOutputStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){if(out.size()+n>16*1024*1024)throw new IOException("响应过大");out.write(b,0,n);}return new JSONObject(out.toString("UTF-8"));}}finally{c.disconnect();}}
 static String error(Exception e){if(e instanceof java.net.SocketTimeoutException)return "连接超时";if(e instanceof java.net.UnknownHostException)return "域名解析失败";if(e instanceof javax.net.ssl.SSLException)return "TLS 连接失败";if(e instanceof JSONException)return "返回内容不是插件 JSON";String m=e.getMessage();return m!=null&&m.matches("HTTP [0-9]{3}")?m:e.getClass().getSimpleName();}
 static String check(SharedPreferences prefs){StringBuilder report=new StringBuilder("Android "+android.os.Build.VERSION.SDK_INT+" · "+android.os.Build.SUPPORTED_ABIS[0]+"\n");try{JSONArray addons=new JSONArray(prefs.getString("addons","[]"));JSONObject claw=null;for(int i=0;i<addons.length();i++){JSONObject a=addons.optJSONObject(i);if(a!=null&&a.optJSONObject("manifest")!=null&&a.optJSONObject("manifest").optString("id").equals("com.torrentclaw.addon")){claw=a;break;}}if(claw==null)return report+"未找到 TorrentClaw 安装记录，请重新导入安装地址。";String base=claw.optString("base").replaceAll("/+$","");if(!base.startsWith("https://")&&!base.startsWith("http://"))return report+"插件地址无效，请重新导入。";report.append("主机：").append(new URL(base).getHost()).append("\n");JSONObject manifest;
  try{manifest=new JSONObject(new String(ClawCompatibleNetwork.bytes(base+"/manifest.json"),"UTF-8"));report.append(ClawCompatibleNetwork.lastReport);}catch(Exception failure){return report+ClawCompatibleNetwork.lastReport+"尚未进入播放器，请把此结果发来。";}
  if(!manifest.optString("id").equals("com.torrentclaw.addon"))return report+"返回的插件身份与 TorrentClaw 不一致。";
  String id="",type="movie";JSONArray history=new JSONArray(prefs.getString("history","[]"));for(int i=0;i<history.length();i++){JSONObject h=history.optJSONObject(i);if(h!=null){String candidate=h.optString("lastEpisode",h.optString("id"));if(candidate.startsWith("tt")){id=candidate;type=h.optString("type","movie");break;}}}
  if(id.isEmpty())return report+"清单正常。没有可用于检测的最近观看条目，请打开影片后再检查。";
  String endpoint=base+"/stream/"+Net.esc(type)+"/"+Net.esc(id)+".json";JSONObject stream=new JSONObject(new String(ClawCompatibleNetwork.bytes(endpoint),"UTF-8"));JSONArray sources=stream.optJSONArray("streams");if(sources==null)return report+"片源：返回内容没有 streams 字段。";report.append("最近观看条目片源：").append(sources.length()).append(" 个\n");return report+(sources.length()==0?"插件可连接，但此条目未返回片源。":"插件已返回片源；播放失败还需检查解码或 P2P 连接。");
 }catch(Exception e){return report+"片源请求："+error(e)+"\n"+ClawCompatibleNetwork.lastReport+"请把此结果发来，便于定位。";}}
}
